import {weatherPlaces,localHour,skyAt,weatherLabel} from './world-time.js';
let key='seoul';try{key=localStorage.getItem('winter-weather-place')||key;}catch{}if(!weatherPlaces[key])key='seoul';
const select=document.querySelector('#weather-place'),output=document.querySelector('#world-weather'),clock=document.querySelector('#world-clock'),phase=document.querySelector('#world-phase');select.value=key;
let weather=null,controller,lighting='night';try{lighting=localStorage.getItem('winter-lighting-mode-v3')||'night';}catch{}const lightingSelect=document.querySelector('#world-lighting-mode');lightingSelect.value=lighting;lightingSelect.onchange=()=>{lighting=lightingSelect.value;try{localStorage.setItem('winter-lighting-mode-v3',lighting);}catch{}tick();};
function tick(){const place=weatherPlaces[key],now=new Date(),hour=localHour(now,place.timezone);clock.textContent=new Intl.DateTimeFormat('ko-KR',{timeZone:place.timezone,hour12:false,hour:'2-digit',minute:'2-digit'}).format(now);clock.dateTime=now.toISOString();phase.textContent=place.name+' · '+skyAt(hour).label;window.labWorldTime={hour:lighting==='night'?21:lighting==='day'?12:hour,actualHour:hour,weather};window.dispatchEvent(new CustomEvent('lab:time',{detail:window.labWorldTime}));}
async function refresh(){controller?.abort();controller=new AbortController();const active=controller,place=weatherPlaces[key];output.textContent='날씨 연결 중';const timer=setTimeout(()=>active.abort(),8000);try{const url=new URL('https://api.open-meteo.com/v1/forecast');Object.entries({latitude:place.latitude,longitude:place.longitude,current:'temperature_2m,weather_code,cloud_cover',timezone:place.timezone,forecast_days:1}).forEach(([k,v])=>url.searchParams.set(k,v));const r=await fetch(url,{signal:active.signal});if(!r.ok)throw Error();const data=await r.json(),c=data.current;if(!Number.isFinite(c?.temperature_2m)||!Number.isInteger(c.weather_code))throw Error();if(active!==controller)return;weather={temperature:c.temperature_2m,code:c.weather_code,cloud:c.cloud_cover||0,updated:Date.now()};output.textContent=Math.round(weather.temperature)+'° · '+weatherLabel(weather.code);output.title='Open-Meteo · '+new Intl.DateTimeFormat('ko-KR',{timeZone:place.timezone,hour:'2-digit',minute:'2-digit'}).format(new Date())+' 갱신';}catch{if(active!==controller)return;weather=null;output.textContent='날씨 연결 안 됨';output.title='현실 시간과 겨울 공간은 계속 작동합니다.';}finally{clearTimeout(timer);if(active===controller)tick();}}
select.addEventListener('change',()=>{key=select.value;try{localStorage.setItem('winter-weather-place',key);}catch{}tick();refresh();});tick();refresh();setInterval(tick,15000);setInterval(refresh,15*60*1000);
